import{_ as d,o as e,c as r,a2 as a}from"./chunks/framework.Bg-Zxr5O.js";const m=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"manual-zh/Linear-Regression.md","filePath":"manual-zh/Linear-Regression.md","lastUpdated":1785684581000}'),n={name:"manual-zh/Linear-Regression.md"};function s(i,t,o,h,p,c){return e(),r("div",null,[...t[0]||(t[0]=[a(`<h4 id="_5-3-2-linear-regression" tabindex="-1">5.3.2 Linear Regression <a class="header-anchor" href="#_5-3-2-linear-regression" aria-label="Permalink to &quot;5.3.2 Linear Regression&quot;">​</a></h4><p>线性回归是一种用于探究一个变量是否及如何与其他变量呈线性关系的技术。如果发现某个变量呈线性关系，则可用于预测该变量未来的取值。</p><p>在下面的示例中，公司的服务部门希望能够预测维修设备所需的时间，以提高其报价准确性。有人提出，维修时间可能与故障间隔时间以及设备的占空比有关。本次调查选择了 0.1 的 p 值。为了探究这一假设，使用了 <code>REGRESSION</code> 命令。该命令不仅检验变量之间是否相关，还识别潜在的线性关系。参见 <a href="./REGRESSION">REGRESSION</a>。</p><p>第一次尝试包含 <strong>duty_cycle</strong>：</p><pre><code>PSPP&gt; get file=&#39;/usr/local/share/pspp/examples/repairs.sav&#39;.
PSPP&gt; regression /variables = mtbf duty_cycle /dependent = mttr.
</code></pre><p>这次尝试产生了如下输出（部分）：</p><table tabindex="0"><thead><tr><th></th><th>Unstandardized Coefficients</th><th>Standardized Coefficients</th><th>t</th><th>Sig.</th><th></th></tr></thead><tbody><tr><td></td><td>B</td><td>Std. Error</td><td>Beta</td><td></td><td></td></tr><tr><td>(Constant)</td><td>10.59</td><td>3.11</td><td>.00</td><td>3.40</td><td>.002</td></tr><tr><td>Mean time between failures (months)</td><td>3.02</td><td>.20</td><td>.95</td><td>14.88</td><td>.000</td></tr><tr><td>Ratio of working to non-working time</td><td>-1.12</td><td>3.69</td><td>-.02</td><td>-.30</td><td>.763</td></tr></tbody></table><p>上表中的系数表明，公式 <em>mttr = 9.81 + 3.1 \\times mtbf + 1.09 \\times duty_cycle</em> 可用于预测维修时间。然而，duty_cycle 系数的显著性值非常高，这将使其成为一个不可靠的预测变量。因此，重复了测试，但省略了 <strong>duty_cycle</strong> 变量：</p><pre><code>PSPP&gt; regression /variables = mtbf /dependent = mttr.
</code></pre><p>第二次尝试产生了如下输出（部分）：</p><table tabindex="0"><thead><tr><th></th><th>Unstandardized Coefficients</th><th>Standardized Coefficients</th><th>t</th><th>Sig.</th><th></th></tr></thead><tbody><tr><td></td><td>B</td><td>Std. Error</td><td>Beta</td><td></td><td></td></tr><tr><td>(Constant)</td><td>9.90</td><td>2.10</td><td>.00</td><td>4.71</td><td>.000</td></tr><tr><td>Mean time between failures (months)</td><td>3.01</td><td>.20</td><td>.94</td><td>15.21</td><td>.000</td></tr></tbody></table><p>这一次，所有系数的显著性都不高于 0.06，表明在 0.06 的水平上，公式 <em>mttr = 10.5 + 3.11 \\times mtbf</em> 是维修时间的可靠预测变量。</p>`,12)])])}const _=d(n,[["render",s]]);export{m as __pageData,_ as default};
